insert into public.moduli_didattici(pre_id,tipo,codice,titolo,descrizione) values
 ('PRE-01','Piscina','BD1','Spiegazioni preliminari','Montaggio e smontaggio Gruppo ARA e pacchetto x trasporto e stivaggio. Funzioni e particolarità varie componenti: bombola, erogatore e GAV. Modalità ingresso in acqua, segnali, spiegazione e ordine sequenza esercizi.'),
 ('PRE-02','Piscina','BD2','Entrata/Uscita e Nuoto Base','Spiegazione entrata/uscita dall''acqua. Prove di nuoto a stile e rana e sostentamento, scivolamento e rana subacquea.'),
 ('PRE-03','Piscina','BD3','Acquaticità e subacquaticità','Rana in immersione, sostentamento, capovolte in raccolta.'),
 ('PRE-04','Piscina','BD4','Esercizi con attrezzatura base','Ingresso per rotazione, nuoto pinnato in superficie e subacqueo, capovolte con attrezzatura, squadra e forbice.'),
 ('PRE-05','Piscina','BD5 / ARA1','Vestizione ARA e prime prove','Montaggio, segnali, vestizione a zaino da seduti, ingresso rotazione acqua bassa, svuotamento parziale, pesata in acqua media, respirazione in superficie con percorso, discesa (compensazione), pivoting sul fondo, percorso in assetto acqua alta.'),
 ('PRE-06','Piscina','BD6 / ARA2','Vestizione acqua alta ed erogatori','Vestizione in acqua a zaino acqua alta, discesa in assetto senza toccare il fondo, togliere/mettere erogatore, trovare/svincolare/rivincolare erogatore di riserva, scambio erogatori, svuotamento con allagamento parziale, lettura strumenti, percorso in assetto.'),
 ('PRE-07','Piscina','BD7 / ARA3','Vestizione seggiolino e GAV','Vestizione in acqua a seggiolino, controlli di coppia, discesa in assetto, uso tasto spurgo, svuotamento completo, assetto neutro statico vicino al fondo, gestione frusta gav (distacco e riattacco), gonfiaggio gav a bocca, percorso in assetto.'),
 ('PRE-08','Piscina','BD8 / ARA4','Prova muta e simulazioni','Vestizione muta, ingresso per rovesciamento, trovare pesata e poi assetto, togliere e mettere pinne sul fondo, togliere e rimettere la maschera, respirazione in coppia (simulata), percorso con uso valvole (assetto negativo e positivo), prova sosta di sicurezza.'),
 ('PRE-09','Piscina','BD2 (Avanzato)','Lancio boa sparabile','Respirazione in coppia e svuotamento maschera da eseguire in assetto e navigazione. Lancio boa sparabile in coppia.'),
 ('PRE-10','Teoria','LEZ-01','L''ATTREZZATURA','Muta, guanti e calzari, zavorra, coltello, torcia, bombola, erogatori, manometro, profondimetro, orologio, jacket, computer, boa sparabile.'),
 ('PRE-11','Teoria','T2+T6+T7 FIPSAS','NOZIONI DI FISICA E TECNICHE DI IMMERSIONE','Ambiente subacqueo - Cenni sulle unità di misura - Stati della materia - Atmosfera e pressione - Legge di Boyle e Mariotte - Principio di Archimede - Legge di Henry - Assorbimento e rilascio gas. Regole base tecniche di immersione - Procedure d''immersione - Segnali - Procedure d''emergenza.'),
 ('PRE-12','Teoria','T3+T5 FIPSAS','ANATOMIA E FISIOLOGIA UMANA APPLICATE ALLA SUBACQUEA','Cenni di anatomia e fisiologia: Tessuti, Apparato circolatorio e respiratorio, Il sistema nervoso, L''orecchio e compensazione, L''occhio.'),
 ('PRE-13','Teoria','T8+T9 FIPSAS','PROGRAMMAZIONE E TABELLE','Tabelle (definizioni, tabelle FIPSAS, utilizzo, FAR, ripetitiva). Pianificazione e programmazione immersione. Preparazione attrezzatura, Parametri e consumi (scorte, profili, calcoli). Computer (Cenni).'),
 ('PRE-14','Teoria','T11 FIPSAS','EMERGENZE E PRIMO SOCCORSO','Immergersi in sicurezza, norme. Emergenze subacquee, Incidenti subacquei. Normativa, legislazione, assicurazioni. Camera iperbarica (cenni). BLS (cenni).'),
 ('PRE-15','Teoria','VERIFICA','Verifica finale','Chiacchierata di verifica sugli argomenti trattati nel corso.'),
 ('PRE-16','Teoria','T12 FIPSAS','BIOLOGIA','Cenni di biologia subacquea.')
